import { useState, type FormEvent } from 'react';
import { JxAlert, JxButton, JxDivider, JxInputField, JxStepper } from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY_VALUES: SignupValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

function validate(step: number, values: SignupValues): Partial<Record<keyof SignupValues, string>> {
  if (step === 0) {
    return {
      name: values.name.trim().length === 0 ? 'Укажите имя' : undefined,
      email: !values.email.includes('@') ? 'Укажите адрес с символом @' : undefined,
      phone: values.phone.replace(/\D/g, '').length < 10 ? 'Укажите номер из 10 цифр' : undefined,
    };
  }
  if (step === 1) {
    return {
      city: values.city.trim().length === 0 ? 'Укажите город' : undefined,
      street: values.street.trim().length === 0 ? 'Укажите улицу и дом' : undefined,
      zip: /^\d{6}$/.test(values.zip) ? undefined : 'Индекс из 6 цифр',
    };
  }
  return {};
}

export default function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(EMPTY_VALUES);
  const [showErrors, setShowErrors] = useState(false);

  const errors = validate(step, values);
  const hasErrors = Object.values(errors).some(Boolean);
  const isLast = step === STEPS.length - 1;

  const set = (key: keyof SignupValues) => (event: { target: { value: string } }) => {
    setValues((current) => ({ ...current, [key]: event.target.value }));
  };

  const errorOf = (key: keyof SignupValues) => (showErrors ? errors[key] : undefined);

  const goBack = () => {
    setShowErrors(false);
    setStep((current) => Math.max(current - 1, 0));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (hasErrors) {
      setShowErrors(true);
      return;
    }
    if (isLast) {
      onSubmit(values);
      return;
    }
    setShowErrors(false);
    setStep((current) => current + 1);
  };

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 20,
        padding: 24,
        maxWidth: 520,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {showErrors && hasErrors ? (
        <JxAlert intent="danger" title="Проверьте поля">
          Чтобы перейти дальше, исправьте отмеченные поля на этом шаге.
        </JxAlert>
      ) : null}

      {step === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <JxInputField
            label="Имя и фамилия"
            required
            autoComplete="name"
            value={values.name}
            onChange={set('name')}
            errorText={errorOf('name')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            value={values.email}
            onChange={set('email')}
            errorText={errorOf('email')}
            helperText="На неё придёт письмо с подтверждением"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            required
            prefix="+7"
            autoComplete="tel"
            value={values.phone}
            onChange={set('phone')}
            errorText={errorOf('phone')}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={values.city}
            onChange={set('city')}
            errorText={errorOf('city')}
          />
          <JxInputField
            label="Улица, дом, квартира"
            required
            autoComplete="street-address"
            value={values.street}
            onChange={set('street')}
            errorText={errorOf('street')}
          />
          <JxInputField
            label="Почтовый индекс"
            required
            inputMode="numeric"
            autoComplete="postal-code"
            value={values.zip}
            onChange={set('zip')}
            errorText={errorOf('zip')}
            helperText="Шесть цифр без пробелов"
          />
        </div>
      ) : null}

      {step === 2 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <JxDivider label="Контакты" />
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
            }}
          >
            <dt style={{ color: 'var(--jx-text-2)' }}>Имя</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{values.name}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Почта</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{values.email}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Телефон</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>+7 {values.phone}</dd>
          </dl>
          <JxDivider label="Адрес" />
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
            }}
          >
            <dt style={{ color: 'var(--jx-text-2)' }}>Город</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{values.city}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Адрес</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{values.street}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Индекс</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{values.zip}</dd>
          </dl>
        </div>
      ) : null}

      <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

